	router.GET(options.BaseURL+"/bookmarks/:id", wrapper.GetBookmark, options.OperationMiddlewares["getBookmark"]...)
	router.PATCH(options.BaseURL+"/bookmarks/:id", wrapper.UpdateBookmark, options.OperationMiddlewares["updateBookmark"]...)
	router.POST(options.BaseURL+"/bookmarks/:id/restore", wrapper.RestoreBookmark, options.OperationMiddlewares["restoreBookmark"]...)
	router.DELETE(options.BaseURL+"/trash", wrapper.EmptyTrash, options.OperationMiddlewares["emptyTrash"]...)
	router.GET(options.BaseURL+"/folders", wrapper.ListFolders, options.OperationMiddlewares["listFolders"]...)
	router.POST(options.BaseURL+"/folders", wrapper.CreateFolder, options.OperationMiddlewares["createFolder"]...)
	router.DELETE(options.BaseURL+"/folders/:id", wrapper.DeleteFolder, options.OperationMiddlewares["deleteFolder"]...)
	router.PATCH(options.BaseURL+"/folders/:id", wrapper.UpdateFolder, options.OperationMiddlewares["updateFolder"]...)
	router.GET(options.BaseURL+"/sync/version", wrapper.GetSyncVersion, options.OperationMiddlewares["getSyncVersion"]...)
